// === GEM SYSTEM ===
// Five gem types with currency values (from reference denominations)
export const GEM_TYPES = {
  yellow: { value: 1,   sprite: 'gem_yellow.png', name: 'Yellow Gem' },
  red:    { value: 10,  sprite: 'gem_red.png',    name: 'Red Gem' },
  purple: { value: 50,  sprite: 'gem_purple.png', name: 'Purple Gem' },
  green:  { value: 80,  sprite: 'gem_green.png',  name: 'Green Gem' },
  black:  { value: 100, sprite: 'gem_black.png',  name: 'Black Gem' },
};

// Block ID -> gem drop config { gem, chance, min, max }
// Higher rarity blocks drop better gems
export const GEM_DROPS = {
  // Common blocks (rarity 1-2): yellow gems
  1:  { gem: 'yellow', chance: 0.3, min: 1, max: 2 },  // Dirt
  2:  { gem: 'yellow', chance: 0.3, min: 1, max: 2 },  // Grass
  11: { gem: 'yellow', chance: 0.2, min: 1, max: 1 },  // Dirt BG
  14: { gem: 'yellow', chance: 0.3, min: 1, max: 2 },  // Sand
  // Uncommon (rarity 3-5): red gems
  3:  { gem: 'red', chance: 0.25, min: 1, max: 1 },     // Stone
  4:  { gem: 'red', chance: 0.25, min: 1, max: 1 },     // Wood
  13: { gem: 'red', chance: 0.3, min: 1, max: 2 },      // Rock
  17: { gem: 'red', chance: 0.25, min: 1, max: 1 },     // Ice
  18: { gem: 'red', chance: 0.25, min: 1, max: 1 },     // Snow
  // Rare (rarity 6-10): purple gems
  5:  { gem: 'purple', chance: 0.2, min: 1, max: 1 },   // Brick
  6:  { gem: 'purple', chance: 0.2, min: 1, max: 1 },   // Glass
  22: { gem: 'purple', chance: 0.25, min: 1, max: 1 },  // Metal
  23: { gem: 'purple', chance: 0.2, min: 1, max: 1 },   // Spikes
  28: { gem: 'purple', chance: 0.25, min: 1, max: 2 },  // Glow
  // Very rare (rarity 15+): green gems
  15: { gem: 'green', chance: 0.3, min: 1, max: 1 },    // Lava
  // Expansion blocks (rarity 3): red gems by default
};

// Get gem drop config for a block ID, with fallback by rarity
export function gemDropFor(blockId) {
  if (GEM_DROPS[blockId]) return GEM_DROPS[blockId];
  const it = ITEMS[blockId];
  if (!it || it.kind !== 'block') return null;
  // Fallback: expansion blocks and others by rarity
  const r = it.rarity || 1;
  if (r >= 15) return { gem: 'green', chance: 0.2, min: 1, max: 1 };
  if (r >= 8)  return { gem: 'purple', chance: 0.15, min: 1, max: 1 };
  if (r >= 4)  return { gem: 'red', chance: 0.15, min: 1, max: 1 };
  return { gem: 'yellow', chance: 0.15, min: 1, max: 1 };
}
